from __future__ import annotations

from .material import layer
from .vector import svg_mask

FIXED_BRAND_KINDS = {'kaspi', 'amazon'}


def glass(mask, fill='#fff', opacity=.88, refraction=.085, specular='outside', shadow=.010):
    return layer(mask, fill, opacity, refraction, specular, shadow, 'glass', 'normal', (0, -2), 0, 1.2, 3.0)


