def glyph_brand_fix(kind):
    if kind == 'kaspi':
        mask = svg_mask(KASPI_MARK, viewbox=(0, 0, 192, 192), target=(210, 192, 814, 824))
        return [glass(mask, '#ffffff', .91, .090, 'inside', .006)]
    if kind == 'amazon':
        mask = svg_mask(AMAZON_SMILE, viewbox=(0, 330, 448, 165), target=(174, 352, 850, 706))
        return [glass(mask, '#17191c', .92, .082, 'inside', .006)]
    return None
